"""Build compact data-health and item-inspector HTML fragments."""
from __future__ import annotations
import json
from pathlib import Path
import pandas as pd
import numpy as np

ROOT=Path(__file__).resolve().parents[1]
OUT=Path.home()/'.codex'/'visualizations'/'2026'/'07'/'11'/'019f5199-c3e5-7a82-bebc-312b5a321a1f'
P=ROOT/'data/public'

def j(x): return json.dumps(x,ensure_ascii=False,separators=(',',':'))
def money(x): return round(float(x),2)

def main():
 OUT.mkdir(parents=True,exist_ok=True)
 items=pd.read_csv(P/'item_master.csv'); stock=pd.read_csv(P/'daily_stock_history.csv'); current=pd.read_csv(P/'current_inventory.csv')
 lines=pd.read_csv(P/'sales_order_lines.csv'); pos=pd.read_csv(P/'purchase_orders.csv'); moves=pd.read_csv(P/'inventory_movements.csv')
 ref='2026-06-30'; start90='2026-04-02'; last90=stock[stock.stock_date>=start90]
 sales90=lines[lines.order_date>=start90].groupby('item_id').agg(sales_qty=('fulfilled_quantity','sum'),revenue=('net_revenue_eur','sum')).reset_index()
 agg=last90.groupby('item_id').agg(stockout_days=('stockout_flag','sum'),backlog_peak=('closing_backlog','max')).reset_index()
 openpo=pos[pos.is_open==1].groupby('item_id').agg(open_po_qty=('ordered_quantity','sum'),next_receipt=('promised_receipt_date','min')).reset_index()
 ix=items.merge(current[['item_id','on_hand_quantity','backorder_quantity','inventory_value_eur']],on='item_id').merge(agg,on='item_id',how='left').merge(sales90,on='item_id',how='left').merge(openpo,on='item_id',how='left')
 ix=ix.fillna({'stockout_days':0,'backlog_peak':0,'sales_qty':0,'revenue':0,'open_po_qty':0,'next_receipt':'NOT_APPLICABLE'})
 ix['gm_pct']=1-ix.current_buy_price_eur/ix.current_list_sell_price_eur
 ix['risk']=np.select([ix.backorder_quantity>0,ix.stockout_days>=6],['Backorder','Recent stockouts'],default='Healthy')
 months=pd.period_range('2025-07','2026-06',freq='M').astype(str).tolist()
 m12=lines[lines.order_date>='2025-07-01'].assign(month=lambda x:x.order_date.str[:7]).groupby(['item_id','month']).net_revenue_eur.sum()
 sales_map={iid:[[m,money(m12.get((iid,m),0))] for m in months] for iid in items.item_id}
 records=[]
 for _,r in ix.iterrows():
  records.append({'id':r.item_id,'name':r.item_name,'dept':r.department,'cat':r.category,'sub':r.subcategory,'supplier':r.primary_supplier_id,'origin':r.sourcing_country,'zone':r.storage_zone,'lifecycle':r.lifecycle_stage,'buy':money(r.current_buy_price_eur),'sell':money(r.current_list_sell_price_eur),'gm':round(float(r.gm_pct)*100,1),'value':money(r.inventory_value_eur),'on':int(r.on_hand_quantity),'bo':int(r.backorder_quantity),'open':int(r.open_po_qty),'next':r.next_receipt,'sales90':int(r.sales_qty),'rev90':money(r.revenue),'stockouts':int(r.stockout_days),'peakbo':int(r.backlog_peak),'risk':r.risk,'monthly_sales':sales_map[r.item_id]})
 inv_eq=(stock.opening_on_hand+stock.receipts+stock.customer_returns+stock.positive_adjustments-stock.shipments-stock.negative_adjustments==stock.closing_on_hand).all()
 bo_eq=(stock.opening_backlog+stock.new_backlog-stock.backlog_fulfilled-stock.backlog_cancelled==stock.closing_backlog).all()
 checks=[['Freshness','Public history reaches reference date','PASS' if stock.stock_date.max()==ref else 'FAIL',stock.stock_date.max()],['Completeness','Expected item-day grain','PASS' if len(stock)==1096000 else 'FAIL',f'{len(stock):,} / 1,096,000'],['Packaging','Packaging equations','PASS' if ((items.units_per_case*items.cases_per_layer*items.layers_per_pallet)==items.units_per_pallet).all() else 'FAIL','checked'],['Accounting','Daily inventory flow','PASS' if inv_eq else 'FAIL','checked'],['Accounting','Daily backlog flow','PASS' if bo_eq else 'FAIL','checked'],['Traceability','Receipt movements link to POs','PASS' if set(moves[moves.movement_type=='SUPPLIER_RECEIPT'].source_transaction_id).issubset(set(pos.po_line_id)) else 'FAIL',f'{len(pos):,} PO lines']]
 monthly=lines.assign(month=lambda x:x.order_date.str[:7]).groupby('month').net_revenue_eur.sum().tail(18)
 dept=ix.groupby('department').inventory_value_eur.sum().sort_values(ascending=False)
 high={'inventory':money(ix.inventory_value_eur.sum()),'backorders':int(ix.backorder_quantity.sum()),'service':round(100*lines[lines.order_date>=start90].fulfilled_quantity.sum()/lines[lines.order_date>=start90].ordered_quantity.sum(),1),'checks':checks,'monthly':[[k,money(v)] for k,v in monthly.items()],'dept':[[k,money(v)] for k,v in dept.items()]}
 build_health(OUT/'business-data-health.html',high); build_item(OUT/'item-inspector.html',records)
 print('Dashboards written to',OUT)

def build_health(path,data):
 path.write_text(f'''<div id="business-health">
<style>
#business-health .health-grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}} #business-health .dash-row{{display:flex;gap:16px;flex-wrap:wrap}} #business-health section{{flex:1 1 320px;min-width:0}} #business-health table{{width:100%;border-collapse:collapse}} #business-health th,#business-health td{{padding:7px 5px;text-align:left;border-bottom:1px solid var(--border)}} #business-health th,.label{{color:var(--muted-foreground);font-weight:500}} #business-health .fail{{color:var(--destructive);font-weight:500}} #business-health svg{{width:100%;height:auto}} #business-health .axis{{stroke:var(--border);stroke-width:1}} #business-health .line{{fill:none;stroke:var(--viz-series-1);stroke-width:2}}
</style>
<section class="health-grid" aria-label="Reference-date business measures"><div class="card viz-stat"><div class="text-muted">Inventory value</div><div class="viz-stat-value" id="inv"></div></div><div class="card viz-stat"><div class="text-muted">Backorders</div><div class="viz-stat-value" id="bo"></div></div><div class="card viz-stat"><div class="text-muted">90-day service</div><div class="viz-stat-value" id="svc"></div></div></section>
<div class="dash-row"><section><h3>Monthly fulfilled revenue</h3><svg id="rev" viewBox="0 0 560 190" role="img" aria-label="Monthly fulfilled revenue"></svg></section><section><h3>Inventory value by department</h3><table><tbody id="dept"></tbody></table></section></div><section><h3>Data health</h3><table><thead><tr><th>Area</th><th>Control</th><th>Status</th><th>Observed</th></tr></thead><tbody id="checks"></tbody></table></section>
</div><script>
(()=>{{const root=document.getElementById('business-health'),d={j(data)},eur=x=>new Intl.NumberFormat('en-GB',{{style:'currency',currency:'EUR',maximumFractionDigits:0}}).format(x),num=x=>new Intl.NumberFormat('en-GB').format(x);root.querySelector('#inv').textContent=eur(d.inventory);root.querySelector('#bo').textContent=num(d.backorders);root.querySelector('#svc').textContent=d.service+'%';root.querySelector('#checks').innerHTML=d.checks.map(x=>`<tr><td>${{x[0]}}</td><td>${{x[1]}}</td><td class="${{x[2]==='PASS'?'':'fail'}}">${{x[2]}}</td><td>${{x[3]}}</td></tr>`).join('');root.querySelector('#dept').innerHTML=d.dept.map(x=>`<tr><th>${{x[0]}}</th><td>${{eur(x[1])}}</td></tr>`).join('');let a=d.monthly,w=560,h=190,p=28,m=Math.max(...a.map(x=>x[1])),pts=a.map((x,i)=>`${{p+i*(w-2*p)/(a.length-1)}},${{h-p-x[1]/m*(h-2*p)}}`).join(' ');root.querySelector('#rev').innerHTML=`<line class="axis" x1="${{p}}" y1="${{h-p}}" x2="${{w-p}}" y2="${{h-p}}"/><polyline class="line" points="${{pts}}"/><text class="label" x="${{p}}" y="16">${{eur(m)}}</text><text class="label" x="${{p}}" y="${{h-6}}">${{a[0][0]}}</text><text class="label" x="${{w-p}}" y="${{h-6}}" text-anchor="end">${{a[a.length-1][0]}}</text>`}})();</script>''',encoding='utf-8')

def build_item(path,records):
 path.write_text(f'''<div id="item-inspector">
<style>
#item-inspector .inspect-controls{{display:flex;gap:12px;flex-wrap:wrap;align-items:end;margin-bottom:12px}} #item-inspector .inspect-controls label{{display:grid;gap:4px;min-width:180px}} #item-inspector .inspect-grid{{display:grid;grid-template-columns:minmax(220px,1fr) minmax(320px,2fr);gap:16px}} #item-inspector .list{{max-height:480px;overflow:auto}} #item-inspector .item-row{{width:100%;text-align:left;padding:8px;border:0;border-bottom:1px solid var(--border);background:transparent;color:var(--foreground)}} #item-inspector .item-row[aria-selected="true"]{{background:var(--accent);color:var(--accent-foreground)}} #item-inspector .item-row small{{display:block;color:var(--muted-foreground)}} #item-inspector .detail-grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:9px}} #item-inspector .detail-grid div{{padding:8px 0;border-bottom:1px solid var(--border)}} #item-inspector .detail-grid span{{display:block;color:var(--muted-foreground);font-size:12px}} #item-inspector table{{width:100%;border-collapse:collapse}} #item-inspector th,#item-inspector td{{padding:6px 4px;text-align:left;border-bottom:1px solid var(--border)}} #item-inspector .warn{{color:var(--destructive);font-weight:500}} #item-inspector svg{{width:100%;height:auto}} #item-inspector .axis{{stroke:var(--border);stroke-width:1}} #item-inspector .sales{{fill:none;stroke:var(--viz-series-1);stroke-width:2}} #item-inspector .label{{fill:var(--muted-foreground);font-size:11px}}
</style>
<div class="inspect-controls"><span class="text-small text-muted">Reference state: 2026-07-01</span><label class="form-label">Find item<input id="search" class="form-control" type="search" placeholder="ID, name, supplier"></label><label class="form-label">Department<select id="department" class="form-select"><option value="">All departments</option></select></label><label class="form-label">Situation<select id="risk-filter" class="form-select"><option value="">All situations</option><option>Backorder</option><option>Recent stockouts</option><option>Healthy</option></select></label></div><div class="inspect-grid"><section><div id="count" class="text-small text-muted"></div><div id="list" class="list" aria-label="Item list"></div></section><section id="detail" aria-live="polite"></section></div>
</div><script>
(()=>{{const root=document.getElementById('item-inspector'),items={j(records)},eur=x=>new Intl.NumberFormat('en-GB',{{style:'currency',currency:'EUR',maximumFractionDigits:0}}).format(x),num=x=>new Intl.NumberFormat('en-GB').format(x);let selected=items[0],shown=[];const q=s=>root.querySelector(s);[...new Set(items.map(x=>x.dept))].sort().forEach(x=>q('#department').insertAdjacentHTML('beforeend',`<option>${{x}}</option>`));function list(){{let term=q('#search').value.toLowerCase(),dep=q('#department').value,risk=q('#risk-filter').value;shown=items.filter(x=>(!dep||x.dept===dep)&&(!risk||x.risk===risk)&&(!term||`${{x.id}} ${{x.name}} ${{x.supplier}}`.toLowerCase().includes(term))).sort((a,b)=>b.value-a.value);if(!shown.includes(selected))selected=shown[0]||items[0];q('#count').textContent=`${{shown.length.toLocaleString()}} items`;q('#list').innerHTML=shown.slice(0,250).map(x=>`<button type="button" class="item-row" data-id="${{x.id}}" aria-selected="${{x.id===selected.id}}"><strong>${{x.id}}</strong> · ${{x.name}}<small>${{x.risk}} · on hand ${{num(x.on)}} · backorder ${{num(x.bo)}}</small></button>`).join('');q('#list').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{{selected=items.find(x=>x.id===b.dataset.id);list();detail()}}));detail()}}function chart(x){{let a=x.monthly_sales,w=600,h=220,p=30,m=Math.max(1,...a.map(v=>v[1])),pts=a.map((v,i)=>`${{p+i*(w-2*p)/(a.length-1)}},${{h-p-v[1]/m*(h-2*p)}}`).join(' ');return `<h3>Last 12 months fulfilled sales revenue</h3><svg viewBox="0 0 ${{w}} ${{h}}" role="img" aria-label="Monthly fulfilled sales revenue"><line class="axis" x1="${{p}}" y1="${{h-p}}" x2="${{w-p}}" y2="${{h-p}}"/><polyline class="sales" points="${{pts}}"/><text class="label" x="${{p}}" y="16">${{eur(m)}}</text><text class="label" x="${{p}}" y="${{h-6}}">${{a[0][0]}}</text><text class="label" x="${{w-p}}" y="${{h-6}}" text-anchor="end">${{a[a.length-1][0]}}</text></svg>`}}function detail(){{let x=selected;q('#detail').innerHTML=`<h3>${{x.id}} · ${{x.name}}</h3><div class="detail-grid"><div><span>Situation</span><b class="${{x.risk==='Healthy'?'':'warn'}}">${{x.risk}}</b></div><div><span>On hand</span><b>${{num(x.on)}}</b></div><div><span>Backorders</span><b>${{num(x.bo)}}</b></div><div><span>Open PO</span><b>${{num(x.open)}}</b></div><div><span>Next PO receipt</span><b>${{x.next}}</b></div><div><span>Inventory value</span><b>${{eur(x.value)}}</b></div><div><span>90-day sales units</span><b>${{num(x.sales90)}}</b></div><div><span>90-day revenue</span><b>${{eur(x.rev90)}}</b></div><div><span>Stockout days</span><b>${{num(x.stockouts)}}</b></div><div><span>Peak backlog</span><b>${{num(x.peakbo)}}</b></div><div><span>Gross margin</span><b>${{x.gm}}%</b></div></div>${{chart(x)}}<h3>Master & supply</h3><table><tbody><tr><th>Hierarchy</th><td>${{x.dept}} / ${{x.cat}} / ${{x.sub}}</td></tr><tr><th>Supplier & origin</th><td>${{x.supplier}} · ${{x.origin}}</td></tr><tr><th>Storage / lifecycle</th><td>${{x.zone}} · ${{x.lifecycle}}</td></tr><tr><th>List / buy price</th><td>${{eur(x.sell)}} / ${{eur(x.buy)}}</td></tr></tbody></table>`}}['#search','#department','#risk-filter'].forEach(s=>{{q(s).addEventListener('input',list);q(s).addEventListener('change',list)}});list()}})();</script>''',encoding='utf-8')

if __name__=='__main__': main()
